import numpy as np
from scipy import ndimage

def transform2(grid, first_hit=False):
    g=np.array(grid); H,W=g.shape
    ones=[(r,c) for r in range(H) for c in range(W) if g[r,c]==1]
    lab,n=ndimage.label(g==2)
    comps={i:set(zip(*np.where(lab==i))) for i in range(1,n+1)}
    cell2comp={cell:i for i,s in comps.items() for cell in s}
    # farthest matching per alignment
    pairs=[]
    for a_ in ones:
        best=None; bd=-1
        for b_ in ones:
            if b_!=a_ and (b_[0]==a_[0] or b_[1]==a_[1]):
                d=abs(b_[0]-a_[0])+abs(b_[1]-a_[1])
                if d>bd: bd=d; best=b_
        if best: pairs.append((a_,best))
    segs=set(); lit=set()
    lines=set()
    for (r,c),(r2,c2) in pairs:
        if r==r2: lines.add(('h',r))
        else: lines.add(('v',c))
        for t in range(min(r,r2),max(r,r2)+1):
            for u in range(min(c,c2),max(c,c2)+1):
                if r==r2 or u==c: segs.add((t,u))
    for kind,v in lines:
        if kind=='h':
            cells=[(v,u) for u in range(W)]
        else:
            cells=[(t,v) for t in range(H)]
        for i,s in comps.items():
            # interior cells of rect: cells not on rect bounding box border
            rs=[r for r,c in s]; cs=[c for r,c in s]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            interior={(r,c) for r,c in s if r0<r<r1 or c0<c<c1}
            if interior & set(cells): lit.add(i)
    out=g.copy()
    for cell in segs: out[cell]=1
    for i in lit:
        for cell in comps[i]: out[cell]=1
    return out.tolist()

